30:   const onClusterClick = useCatchCallback(async (event) => {
31:     if (disabledRef.current) return;
32:     event.preventDefault();
33:     const feature = event.features[0];
34:     const zoom = await map
35:       .getSource(feature.source)
36:       .getClusterExpansionZoom(feature.properties.cluster_id);
37:     map.easeTo({ center: feature.geometry.coordinates, zoom });
38:   }, []);
39: 
40:   const layers = [
41:     {
42:       type: 'symbol',
43:       filter: ['!has', 'point_count'],
44:       layout: showTitles
45:         ? {
46:             'icon-image': '{image}',
47:             'icon-size': iconScale,
48:             'icon-allow-overlap': true,
49:             'text-field': '{title}',
50:             'text-allow-overlap': true,
