55:             'symbol-sort-key': ['get', 'id'],
56:           }
57:         : {
58:             'icon-image': '{image}',
59:             'icon-size': iconScale,
60:             'icon-allow-overlap': true,
61:             'symbol-sort-key': ['get', 'id'],
62:           },
