64:       ...(onClick
65:         ? { on: { mouseenter: onMouseEnter, mouseleave: onMouseLeave, click: onMarkerClick } }
66:         : {}),
67:     },
68:   ];
69: 
70:   if (direction) {
71:     layers.push({
72:       key: 'direction',
73:       type: 'symbol',
74:       filter: ['all', ['!has', 'point_count'], ['==', 'direction', true]],
75:       layout: {
76:         'icon-image': 'direction',
