119:             title: title || '',
120:             rotation: rotation || 0,
121:             direction: showDirection || false,
122:           },
123:         }),
124:       ),
125:     },
126:     dataDeps: [markers, showTitles],
127:   });
128: 
129:   return null;
130: };
